import fs from 'fs';
import path from 'path';
import zlib from 'zlib';

const expectedBase = '0.27.2';
const targetVersion = '0.28.0';
const root = process.cwd();
const files = {"package.json":"","src/App.tsx":"","src/styles.css":"","src/components/GlobalSearch.tsx":"","src/components/GlobalSearch.css":"","src/views/MyWorkspace.tsx":"","src/views/MyWorkspace.css":"","src/views/DataQuality.tsx":"","src/views/DataQuality.css":"","src/views/Cmdb.tsx":"","src/views/Cmdb.css":"","src/lib/storage.ts":"","src/data/seed.json":"","RELEASE_NOTES.md":"","RELEASE_NOTES_0.28.md":"","README_NASADENIE_0.28.txt":"","SMART_WORKSPACE_0.28.md":""};
function readJson(file) { try { return JSON.parse(fs.readFileSync(file, 'utf8')); } catch { return null; } }
function stamp() { return new Date().toISOString().replace(/[:.]/g, '-'); }
const pkgPath = path.join(root, 'package.json');
if (!fs.existsSync(pkgPath)) { console.error('ERROR: Run installer in project root.'); process.exit(1); }
const current = String(readJson(pkgPath)?.version || '');
if (current !== expectedBase && current !== targetVersion) { console.error(`ERROR: Expected ${expectedBase} (or already ${targetVersion}), found ${current || 'unknown'}.`); process.exit(1); }
const backupRoot = path.join(root, `backup-before-v0280-${stamp()}`); fs.mkdirSync(backupRoot, { recursive: true });
let written = 0;
for (const [rel, data] of Object.entries(files)) { const destination = path.join(root, rel); if (fs.existsSync(destination)) { const backup = path.join(backupRoot, rel); fs.mkdirSync(path.dirname(backup), { recursive: true }); fs.copyFileSync(destination, backup); } fs.mkdirSync(path.dirname(destination), { recursive: true }); fs.writeFileSync(destination, zlib.gunzipSync(Buffer.from(data, 'base64'))); written += 1; console.log('WRITE', rel); }
for (const cache of ['dist', '.vite', 'node_modules/.vite']) { const p = path.join(root, cache); if (fs.existsSync(p)) fs.rmSync(p, { recursive: true, force: true }); }
if (String(readJson(pkgPath)?.version) !== targetVersion) { console.error('ERROR: package version verification failed.'); process.exit(2); }
const app = fs.readFileSync(path.join(root, 'src/App.tsx'), 'utf8'); const cmdb = fs.readFileSync(path.join(root, 'src/views/Cmdb.tsx'), 'utf8');
if (!app.includes('Moje centrum') || !app.includes('GlobalSearch') || !cmdb.includes('Hromadná úprava') || !cmdb.includes('Uložené pohľady')) { console.error('ERROR: Smart Workspace verification failed.'); process.exit(3); }
console.log(`VERIFIED: v0.28.0 Smart Workspace installed. ${written} files written.`); console.log('Backup:', backupRoot);
